package app.dayflow;
import android.content.*;
import android.content.pm.*;
import android.net.Uri;
import android.widget.*;
import com.google.android.material.materialswitch.MaterialSwitch;
import androidx.core.content.FileProvider;
import org.json.*;
import java.io.*;
import java.util.*;

/** Installed APK extensions communicate with narrow Intents; no downloaded dex/JAR execution. */
final class ExtensionHub {
 static final String ACTION="app.dayflow.action.EXTENSION",OCR_PACKAGE="app.dayflow.ocr";
 static void show(MainActivity a){LinearLayout page=a.fullPage("扩展与存储",a::home);page.addView(Ui.text(a,"扩展中心",25,true));page.addView(Ui.help(a,"大型功能使用独立APK插件：按需安装、单独进程运行，卸载不影响已经导入的日程与笔记。只向插件提供本次授权的输入；识别结果先进入收集箱，笔记保存交回本体同步。"));List<ResolveInfo> providers=a.getPackageManager().queryIntentActivities(new Intent(ACTION),PackageManager.GET_META_DATA);if(providers.isEmpty())page.addView(Ui.help(a,"尚未安装扩展。离线OCR插件可以单独下载。"));for(ResolveInfo info:providers){String pkg=info.activityInfo.packageName;LinearLayout body=Ui.padded(a);body.addView(Ui.text(a,info.loadLabel(a.getPackageManager()).toString(),18,true));MaterialSwitch enabled=new MaterialSwitch(a);enabled.setText("启用扩展");enabled.setChecked(a.prefs.getBoolean("plugin_enabled_"+pkg,true));enabled.setOnCheckedChangeListener((v,on)->a.prefs.edit().putBoolean("plugin_enabled_"+pkg,on).apply());body.addView(enabled);body.addView(Ui.help(a,pkg+(a.getPackageManager().checkSignatures(a.getPackageName(),pkg)==PackageManager.SIGNATURE_MATCH?" · 同发布者签名":" · 第三方签名，使用前核对来源")));if(pkg.equals(OCR_PACKAGE))body.addView(Ui.button(a,"选图离线识别",true,()->pickOcr(a)));else if(pkg.equals(DocumentPlugins.MD))body.addView(Ui.help(a,"从笔记的完整Markdown入口打开，仅共享所选笔记。"));else if(pkg.equals(DocumentPlugins.ALMANAC))body.addView(Ui.button(a,"打开黄历",false,()->DocumentPlugins.almanac(a,java.time.LocalDate.now())));else if(pkg.equals(AssistantApi.PACKAGE))body.addView(Ui.button(a,"开放API设置",false,()->AssistantApi.show(a)));else body.addView(Ui.button(a,"打开扩展",false,()->open(a,info)));body.addView(Ui.button(a,"系统存储与卸载",false,()->a.startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+pkg)))));page.addView(body);}
  page.addView(Ui.button(a,"下载完整Markdown插件",false,()->a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://github.com/cniv14/DayFlow/releases/latest/download/DayFlow-markdown.apk")))));page.addView(Ui.button(a,"下载黄历插件",false,()->a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://github.com/cniv14/DayFlow/releases/latest/download/DayFlow-almanac.apk")))));if(a.prefs.contains("plugin_document"))page.addView(Ui.button(a,"恢复插件暂存文档",false,()->DocumentPlugins.recover(a)));String abi=Arrays.asList(android.os.Build.SUPPORTED_ABIS).contains("arm64-v8a")?"arm64":Arrays.asList(android.os.Build.SUPPORTED_ABIS).contains("armeabi-v7a")?"armv7":"";if(!abi.isEmpty())page.addView(Ui.button(a,"下载可选离线OCR（"+abi+"）",false,()->a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://github.com/cniv14/DayFlow/releases/latest/download/DayFlow-ocr-"+abi+".apk")))));page.addView(Ui.button(a,"网页、HTML课表与日历导入",false,()->WebImports.show(a)));page.addView(Ui.button(a,"专注计时",false,()->FocusTimer.show(a,null)));page.addView(Ui.button(a,"项目看板",false,()->ProjectBoard.show(a,"planned",0)));page.addView(Ui.button(a,"长期项目打卡",false,()->CheckIns.list(a)));page.addView(Ui.button(a,"存储占用与缓存管理",false,()->storage(a)));
 }
 private static void open(MainActivity a,ResolveInfo info){String pkg=info.activityInfo.packageName;if(!a.prefs.getBoolean("plugin_enabled_"+pkg,true)){a.message("扩展已停用");return;}Intent request=new Intent(ACTION).setComponent(new ComponentName(pkg,info.activityInfo.name)).putExtra("dayflow_protocol",1);Runnable launch=()->{try{a.startActivityForResult(request,114);}catch(Exception e){a.message(e.getMessage());}};if(a.getPackageManager().checkSignatures(a.getPackageName(),pkg)!=PackageManager.SIGNATURE_MATCH){LinearLayout page=a.fullPage("第三方扩展",()->show(a));page.addView(Ui.help(a,"此插件由其他发布者签名，本次只打开插件，不分享笔记、账号或密钥。返回内容仍需确认。\n"+pkg));page.addView(Ui.button(a,"打开此扩展",true,launch));}else launch.run();}
 static void pickOcr(MainActivity a){if(!a.prefs.getBoolean("plugin_enabled_"+OCR_PACKAGE,true)){a.message("请先在扩展中心启用离线OCR");return;}try{a.getPackageManager().getPackageInfo(OCR_PACKAGE,0);a.pickFile(112,"image/*");}catch(PackageManager.NameNotFoundException e){show(a);a.message("请先安装可选离线OCR插件");}}
 static void runOcr(MainActivity a,Uri source){if(a.getPackageManager().checkSignatures(a.getPackageName(),OCR_PACKAGE)!=PackageManager.SIGNATURE_MATCH){a.message("OCR插件签名与日栖不一致，请从本项目发布页安装");return;}final Uri[] shared={null};a.job(()->{File dir=new File(a.getCacheDir(),"shared-images");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException("无法建立图片缓存");File file=new File(dir,"ocr-input.jpg");try(InputStream in=a.getContentResolver().openInputStream(source);OutputStream out=new FileOutputStream(file)){if(in==null)throw new IOException("无法读取图片");byte[] buffer=new byte[8192];int count,total=0;while((count=in.read(buffer))!=-1){total+=count;if(total>12*1024*1024)throw new IOException("图片超过12MiB，请先裁剪");out.write(buffer,0,count);}}shared[0]=FileProvider.getUriForFile(a,"app.dayflow.files",file);return "图片已准备，将交给本机离线OCR插件";},()->{if(shared[0]!=null)try{Intent request=new Intent("app.dayflow.action.OCR").setPackage(OCR_PACKAGE).setDataAndType(shared[0],"image/jpeg").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION).putExtra("dayflow_protocol",1);request.setClipData(ClipData.newRawUri("本次识别图片",shared[0]));a.startActivityForResult(request,114);}catch(Exception e){a.message("无法打开OCR扩展，请检查安装与版本");}});}
 static void ocrResult(MainActivity a,Intent data){try{String error=data.getStringExtra("dayflow_error");if(error!=null&&!error.isEmpty())throw new Exception(error);String proposals=data.getStringExtra("dayflow_items");if(proposals!=null){if(proposals.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>48000)throw new Exception("扩展返回内容过大");JSONArray input=new JSONArray(proposals),out=new JSONArray();if(input.length()>40)throw new Exception("扩展最多返回40条待确认事项");for(int i=0;i<input.length();i++){JSONObject item=input.getJSONObject(i),r=Data.make("inbox",item.optString("title","扩展待确认"));for(String field:Arrays.asList("content","start_at","end_at","location","time_hint","due_date"))if(item.has(field))r.put(field,item.optString(field));r.put("confirmation_status","pending").put("source","扩展待确认").put("proposed_kind",Arrays.asList("event","task","course","project").contains(item.optString("kind"))?item.optString("kind"):"event");Data.validate(r);out.put(r);}a.importPreview(out);return;}String text=data.getStringExtra(Intent.EXTRA_TEXT);if(text==null||text.trim().isEmpty())throw new Exception("扩展未返回可用文字");if(text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>48000)throw new Exception("扩展返回文字过多，请分区域识别");a.showCaptureText(text);}catch(Exception e){a.message(e.getMessage());}finally{cleanupOcr(a);}}
 static void cleanupOcr(MainActivity a){try{a.revokeUriPermission(OCR_PACKAGE,FileProvider.getUriForFile(a,"app.dayflow.files",new File(a.getCacheDir(),"shared-images/ocr-input.jpg")),Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}new File(a.getCacheDir(),"shared-images/ocr-input.jpg").delete();}
 private static long size(File file){if(!file.exists())return 0;if(file.isFile())return file.length();long total=0;File[] children=file.listFiles();if(children!=null)for(File child:children)total+=size(child);return total;}
 private static String mb(long bytes){return String.format(Locale.CHINA,"%.2f MiB",bytes/1048576.0);}
 private static void storage(MainActivity a){LinearLayout page=a.fullPage("存储管理",()->show(a));page.addView(Ui.text(a,"本机占用",24,true));page.addView(Ui.help(a,"应用主包："+mb(new File(a.getApplicationInfo().sourceDir).length())+"\n数据与Markdown："+mb(size(a.getFilesDir()))+"\n数据库："+mb(size(a.getDatabasePath("dayflow.db")))+"\n可清理缓存："+mb(size(a.getCacheDir()))));page.addView(Ui.help(a,"只清理图片与临时缓存；笔记、同步数据、打卡和草稿不清除。OCR模型存放在独立插件内，卸载插件可释放其占用。已删除事项的同步标记保留，避免其他设备将其恢复。"));page.addView(Ui.button(a,"清理临时缓存",false,()->a.job(()->{File root=a.getCacheDir().getCanonicalFile();clear(root,root);return "已清理临时缓存，正式数据与草稿保留";},()->storage(a))));}
 private static void clear(File root,File file)throws IOException{File real=file.getCanonicalFile();if(!real.toPath().startsWith(root.toPath()))return;File[] files=file.listFiles();if(files!=null)for(File child:files){if(child.isDirectory())clear(root,child);if(!child.delete()&&child.exists())throw new IOException("部分缓存正在使用，请稍后重试");}}
}
